16	// buildCLI 将命令行编译到临时目录，供跨进程测试使用。仅使用标准库，离线可编译。
17	func buildCLI(t *testing.T) string {
18		t.Helper()
19		binary := filepath.Join(t.TempDir(), "govflow")
20		cmd := exec.Command("go", "build", "-o", binary, "./cmd/govflow")
21		// 测试工作目录为模块下的 govflow/，仓库根目录在上一层。
22		cmd.Dir = ".."
23		var out bytes.Buffer
24		cmd.Stderr = &out
25		if err := cmd.Run(); err != nil {
26			t.Fatalf("build cli: %v\n%s", err, out.String())
27		}
28		return binary
29	}
30	
31	func runCLI(t *testing.T, binary, state string, args ...string) (stdout, stderr string, code int) {
32		t.Helper()
33		// main 以第一个参数作为子命令，--state 必须位于子命令之后。
34		full := append([]string{args[0], "--state", state}, args[1:]...)
35		cmd := exec.Command(binary, full...)
36		var so, se bytes.Buffer
37		cmd.Stdout = &so
38		cmd.Stderr = &se
39		err := cmd.Run()
40		if ee, ok := err.(*exec.ExitError); ok {
41			code = ee.ExitCode()
42		} else if err != nil {
43			t.Fatalf("run cli %v: %v", args, err)
44		}
45		return so.String(), se.String(), code
46	}
