101	// TestCrossProcessDifferentProposals：40 个进程各花 10，资金库只有 100，
102	// 必须恰好 10 个成功，且所有判断基于实际已提交余额。
103	func TestCrossProcessDifferentProposals(t *testing.T) {
104		binary := buildCLI(t)
105		state := filepath.Join(t.TempDir(), "treasury.json")
106		if _, _, code := runCLI(t, binary, state, "init", "--balance", "100"); code != 0 {
107			t.Fatal("init failed")
108		}
109		const n = 40
110		for i := 0; i < n; i++ {
111			if _, _, code := runCLI(t, binary, state, "register", "--id", "gip-"+itoa(i),
112				"--timelock", "0", "--action", "transfer:acct:10"); code != 0 {
113				t.Fatalf("register %d failed", i)
114			}
115		}
116	
117		var wg sync.WaitGroup
118		successes := make(chan int, n)
119		failures := make(chan string, n)
120		start := make(chan struct{})
121		for i := 0; i < n; i++ {
122			wg.Add(1)
123			go func(i int) {
124				defer wg.Done()
125				<-start
126				_, se, code := runCLI(t, binary, state, "execute", "--id", "gip-"+itoa(i), "--now", "0")
127				if code == 0 {
128					successes <- 1
129				} else {
130					failures <- se
131				}
132			}(i)
133		}
134		close(start)
135		wg.Wait()
136		close(successes)
137		close(failures)
138		got := 0
139		for range successes {
140			got++
141		}
142		for msg := range failures {
143			if !strings.Contains(msg, "insufficient") {
144				t.Fatalf("unexpected failure reason: %s", msg)
145			}
146		}
147		if got != 10 {
148			t.Fatalf("cross-process successes=%d, want 10", got)
149		}
150	
151		so, _, _ := runCLI(t, binary, state, "balances", "--json")
152		if !strings.Contains(so, `"treasury": 0`) || !strings.Contains(so, `"acct": 100`) {
153			t.Fatalf("final balances wrong:\n%s", so)
154		}
155		so, _, _ = runCLI(t, binary, state, "receipts", "--json")
156		if strings.Count(so, `"proposal_id"`) != 10 {
157			t.Fatalf("expected 10 receipts, got:\n%s", so)
158		}
159	}
