235	// TestCrossProcessVotingLifecycle：通过 CLI 跨进程完成创建→委托投票→计票→执行，
236	// 并验证重复创建/投票/计票的幂等与冲突语义。
237	func TestCrossProcessVotingLifecycle(t *testing.T) {
238		binary := buildCLI(t)
239		state := filepath.Join(t.TempDir(), "treasury.json")
240		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
241			t.Fatal("init failed")
242		}
243		create := []string{"create-vote", "--id", "gip-vote-1",
244			"--member", "alice:300", "--member", "bob:200", "--member", "carol:100", "--member", "dave:400",
245			"--delegate", "bob:alice", "--delegate", "carol:alice",
246			"--quorum", "600", "--start", "100", "--deadline", "200", "--timelock", "300",
247			"--action", "transfer:audits:100"}
248		if _, se, code := runCLI(t, binary, state, create...); code != 0 {
249			t.Fatalf("create-vote failed: %s", se)
250		}
251		// 成员与委托换序的完全相同重试：成功且不改动状态。
252		retry := []string{"create-vote", "--id", "gip-vote-1",
253			"--member", "dave:400", "--member", "carol:100", "--member", "bob:200", "--member", "alice:300",
254			"--delegate", "carol:alice", "--delegate", "bob:alice",
255			"--quorum", "600", "--start", "100", "--deadline", "200", "--timelock", "300",
256			"--action", "transfer:audits:100"}
257		if _, se, code := runCLI(t, binary, state, retry...); code != 0 {
258			t.Fatalf("identical create retry should succeed: %s", se)
259		}
260		// 内容不同的重试冲突（多一个动作，动作按原文及顺序比较）。
261		conflict := append(append([]string{}, create...), "--action", "transfer:legal:1")
262		if _, _, code := runCLI(t, binary, state, conflict...); code != 1 {
263			t.Fatalf("conflicting create should exit 1, got %d", code)
264		}
265		// register 不能占用投票提案编号。
266		if _, se, code := runCLI(t, binary, state, "register", "--id", "gip-vote-1",
267			"--timelock", "300", "--action", "transfer:audits:100"); code != 1 {
268			t.Fatalf("register over voting id should fail: %s", se)
269		}
270	
271		// 委托出去的成员投票被拒；非名单成员被拒。
272		if _, se, code := runCLI(t, binary, state, "vote", "--id", "gip-vote-1",
273			"--voter", "bob", "--choice", "for", "--now", "150"); code != 1 || !strings.Contains(se, "delegated") {
274			t.Fatalf("delegated member vote code=%d: %s", code, se)
275		}
276		if _, se, code := runCLI(t, binary, state, "vote", "--id", "gip-vote-1",
277			"--voter", "ghost", "--choice", "for", "--now", "150"); code != 1 || !strings.Contains(se, "not on the member roster") {
278			t.Fatalf("non-member vote code=%d: %s", code, se)
279		}
280	
281		// 代表 alice（归集 600）赞成；相同选择跨进程重试返回首次时间。
282		if so, se, code := runCLI(t, binary, state, "vote", "--id", "gip-vote-1",
283			"--voter", "alice", "--choice", "for", "--now", "120", "--json"); code != 0 ||
284			!strings.Contains(so, `"weight": 600`) {
285			t.Fatalf("alice vote code=%d so=%s se=%s", code, so, se)
286		}
287		if so, _, code := runCLI(t, binary, state, "vote", "--id", "gip-vote-1",
288			"--voter", "alice", "--choice", "for", "--now", "180", "--json"); code != 0 ||
289			!strings.Contains(so, `"voted_at": 120`) {
290			t.Fatalf("identical vote retry must return first record: %s", so)
291		}
292		// 改投冲突。
293		if _, se, code := runCLI(t, binary, state, "vote", "--id", "gip-vote-1",
294			"--voter", "alice", "--choice", "against", "--now", "120"); code != 1 ||
295			!strings.Contains(se, "changing the vote") {
296			t.Fatalf("change vote code=%d: %s", code, se)
297		}
298	
299		// 截止前计票拒绝。
300		if _, se, code := runCLI(t, binary, state, "tally", "--id", "gip-vote-1", "--now", "199"); code != 1 ||
301			!strings.Contains(se, "still open") {
302			t.Fatalf("early tally code=%d: %s", code, se)
303		}
304		// 截止时刻计票：600 赞成、0 反对、达到法定人数 => passed。
305		if so, se, code := runCLI(t, binary, state, "tally", "--id", "gip-vote-1",
306			"--now", "200", "--json"); code != 0 || !strings.Contains(so, `"passed": true`) {
307			t.Fatalf("tally code=%d so=%s se=%s", code, so, se)
308		}
309		// 计票后窗口内新票也拒绝。
310		if _, se, code := runCLI(t, binary, state, "vote", "--id", "gip-vote-1",
311			"--voter", "dave", "--choice", "against", "--now", "150"); code != 1 ||
312			!strings.Contains(se, "already been tallied") {
313			t.Fatalf("post-tally vote code=%d: %s", code, se)
314		}
315		// 再次计票返回首次时间。
316		if so, _, code := runCLI(t, binary, state, "tally", "--id", "gip-vote-1",
317			"--now", "999", "--json"); code != 0 || !strings.Contains(so, `"tallied_at": 200`) {
318			t.Fatalf("repeat tally: %s", so)
319		}
320	
321		// 通过后直接由 execute 执行，无需再登记；时间锁未到拒绝。
322		if _, _, code := runCLI(t, binary, state, "execute", "--id", "gip-vote-1", "--now", "299"); code != 1 {
323			t.Fatalf("execute before timelock should fail")
324		}
325		if _, _, code := runCLI(t, binary, state, "execute", "--id", "gip-vote-1", "--now", "300"); code != 0 {
326			t.Fatalf("execute voted proposal failed")
327		}
328		if so, _, _ := runCLI(t, binary, state, "balances", "--json"); !strings.Contains(so, `"treasury": 900`) ||
329			!strings.Contains(so, `"audits": 100`) {
330			t.Fatalf("balances after voted execution:\n%s", so)
331		}
332		// 已执行提案不退回通过：再次执行返回首次凭据。
333		if so, _, _ := runCLI(t, binary, state, "execute", "--id", "gip-vote-1",
334			"--now", "9999", "--json"); !strings.Contains(so, `"executed_at": 300`) {
335			t.Fatalf("re-execute should return first receipt: %s", so)
336		}
337		// 查询包含逐票明细、委托路径与已执行状态。
338		so, _, _ := runCLI(t, binary, state, "proposal", "--id", "gip-vote-1", "--json")
339		if !strings.Contains(so, `"state": "executed"`) ||
340			!strings.Contains(so, `"representative": "alice"`) ||
341			!pathJSONRe.MatchString(so) {
342			t.Fatalf("proposal query missing delegation path/ballot/state:\n%s", so)
343		}
344	}
345	
346	var pathJSONRe = regexp.MustCompile(`"path": \[\s+"bob",\s+"alice"\s+\]`)
