407	// 删除句柄后状态文件仍是完整 JSON 且可再次打开。
408	func TestReopenAfterClose(t *testing.T) {
409		path := filepath.Join(t.TempDir(), "treasury.json")
410		store, err := InitTreasury(path, 5)
411		if err != nil {
412			t.Fatal(err)
413		}
414		mustRegister(t, store, "gip-1", 0, "transfer:a:5")
415		if _, err := store.Execute("gip-1", 0); err != nil {
416			t.Fatal(err)
417		}
418		if err := store.Close(); err != nil {
419			t.Fatal(err)
420		}
421		raw, err := os.ReadFile(path)
422		if err != nil || !strings.Contains(string(raw), stateMagic) {
423			t.Fatalf("state file missing or bad after close: %v", err)
