435	// TestCLIRejectsCaseVariantField：固定字段名的大小写变体让整个状态文件被拒绝，
436	// 命令行将原因（含问题字段）写到标准错误并以状态码 1 退出，文件不被改写。
437	func TestCLIRejectsCaseVariantField(t *testing.T) {
438		binary := buildCLI(t)
439		dir := t.TempDir()
440		state := filepath.Join(dir, "treasury.json")
441		if _, se, code := runCLI(t, binary, state, "init", "--balance", "100"); code != 0 {
442			t.Fatalf("init exit=%d: %s", code, se)
443		}
444		raw, err := os.ReadFile(state)
445		if err != nil {
446			t.Fatal(err)
447		}
448		corrupt := strings.Replace(string(raw), `"treasury": 100`, `"Treasury": 100`, 1)
449		if corrupt == string(raw) {
450			t.Fatalf("setup: treasury field not found in %s", raw)
451		}
452		if err := os.WriteFile(state, []byte(corrupt), 0o600); err != nil {
453			t.Fatal(err)
454		}
455		so, se, code := runCLI(t, binary, state, "balances")
456		if code != 1 {
457			t.Fatalf("balances exit=%d, want 1 (stdout=%q stderr=%q)", code, so, se)
458		}
459		if !strings.Contains(se, "corrupt") || !strings.Contains(se, `"Treasury"`) {
460			t.Fatalf("stderr should name the corruption and the field, got %q", se)
461		}
462		// 不提供部分余额信息，也不整理或写回原文件。
463		if so != "" {
