828	// TestCLIColonsInMemberIDs：成员编号允许冒号出现在开头（":alice"）或中间
829	// （"team:bob"）。委托原文 ":alice:team:bob" 必须被理解为 :alice 把权重
830	// 委托给 team:bob，而不是按第一个冒号误切成空委托人。查询完整保留两个编号
831	// 与委托路径；team:bob 作为最终代表投出票重 100，:alice 已委托出去不能直投。
832	func TestCLIColonsInMemberIDs(t *testing.T) {
833		binary := buildCLI(t)
