836			t.Fatal("init failed")
837		}
838		base := createVoteArgs{
839			id:        "gip-colon",
840			members:   []string{":alice:70", "team:bob:30"},
841			delegates: []string{":alice:team:bob"},
842			quorum:    "100",
843		}
844		if _, se, code := runCreateVote(t, binary, state, base); code != 0 {
845			t.Fatalf("create with colon-leading delegator failed, exit=%d: %s", code, se)
846		}
847	
848		// 文本查询：两个编号逐字保留，委托路径从 :alice 到 team:bob。
849		so, se, code := runCLI(t, binary, state, "proposal", "--id", base.id)
850		if code != 0 {
851			t.Fatalf("text proposal query exit=%d: %s", code, se)
852		}
853		for _, want := range []string{
854			"member :alice weight=70 path=:alice->team:bob",
855			"member team:bob weight=30 representative=self",
856		} {
857			if !strings.Contains(so, want) {
858				t.Fatalf("text query missing %q:\n%s", want, so)
859			}
860		}
861	
862		// JSON 查询：编号大小写、冒号位置逐字保留，路径含首尾两个完整编号。
863		jo, je, jcode := runCLI(t, binary, state, "proposal", "--id", base.id, "--json")
864		if jcode != 0 {
865			t.Fatalf("json proposal query exit=%d: %s", jcode, je)
866		}
867		for _, want := range []string{
868			`"id": ":alice"`,
869			`"id": "team:bob"`,
870			`"path": [
871	        ":alice",
872	        "team:bob"
873	      ]`,
874			`"delegate": "team:bob"`,
875			`"direct_to": "team:bob"`,
876		} {
877			if !strings.Contains(jo, want) {
878				t.Fatalf("json query missing %q:\n%s", want, jo)
879			}
880		}
881	
882		// 最终代表 team:bob 代表沿途全部 70+30=100 权重投票。
883		if vo, ve, vcode := runCLI(t, binary, state, "vote", "--id", base.id,
884			"--voter", "team:bob", "--choice", "for", "--now", "50", "--json"); vcode != 0 ||
885			!strings.Contains(vo, `"representative": "team:bob"`) || !strings.Contains(vo, `"weight": 100`) {
886			t.Fatalf("team:bob vote exit=%d so=%s se=%s", vcode, vo, ve)
887		}
888		// :alice 已委托出去，直接投票被域错误拒绝。
889		if _, ve, vcode := runCLI(t, binary, state, "vote", "--id", base.id,
890			"--voter", ":alice", "--choice", "for", "--now", "50"); vcode != 1 ||
891			!strings.Contains(ve, "may not vote directly") {
