1	// Command govflow is the DAO 治理提案与执行平台 entry point.
2	package main
3	
4	import (
5		"encoding/json"
6		"errors"
7		"flag"
8		"fmt"
9		"io"
10		"os"
11		"sort"
12		"strconv"
13		"strings"
14	
15		"github.com/gzhysuiioo/govflow-proposals/govflow"
16	)
17	
18	const versionText = "govflow 0.2.0"
19	
20	func main() {
21		command := "demo"
22		if len(os.Args) > 1 {
23			command = os.Args[1]
24		}
25		args := os.Args[2:]
26		switch command {
27		case "demo":
28			runDemo()
29		case "version":
30			fmt.Println(versionText)
31		case "help", "-h", "--help":
32			usage()
33		case "init":
34			runInit(args)
35		case "register":
36			runRegister(args)
37		case "create-vote":
38			runCreateVote(args)
39		case "vote":
40			runVote(args)
41		case "tally":
42			runTally(args)
43		case "execute":
44			runExecute(args)
45		case "balances":
46			runBalances(args)
47		case "proposal":
48			runProposal(args)
49		case "proposals":
50			runProposals(args)
51		case "receipt":
52			runReceipt(args)
53		case "receipts":
54			runReceipts(args)
55		default:
56			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
57			usage()
58			os.Exit(2)
59		}
60	}
