489		}
490		defer store.Close()
491		receipt, err := store.Execute(*id, now)
492		if err != nil {
493			var derr *govflow.DurabilityError
494			if receipt != nil && errors.As(err, &derr) {
495				// 状态文件已替换成功：转账、executed 状态与凭据已写入，只是
496				// 目录同步失败、持久性未确认。标准输出照常给出已写入的凭据，
497				// 标准错误说明告警（提案编号 + 具体失败原因），退出码仍为 1。
498				if cf.asJSON {
499					emitJSON(receipt)
500				} else {
501					printReceiptText(receipt, false)
502				}
503				fmt.Fprintf(os.Stderr, "warning: proposal %s: execution record written but durability not confirmed: %v\n", *id, derr.Cause)
504				os.Exit(1)
505			}
506			fail(err)
507		}
508		if cf.asJSON {
509			emitJSON(receipt)
510			return
511		}
512		printReceiptText(receipt, false)
513	}
