515	func runBalances(args []string) {
516		cf := newCmdFlags("balances")
517		account := cf.fs.String("account", "", "show only this recipient account balance (unknown accounts are 0)")
518		cf.parse(args)
519		store, err := govflow.Open(cf.state)
520		if err != nil {
521			fail(err)
522		}
523		defer store.Close()
524		// 一次快照读取保证资金库与账户余额来自同一份已提交状态，
525		// 不会把并发执行前后的数字拼在一起。
526		snapshot, err := store.BalanceSnapshot()
527		if err != nil {
528			fail(err)
529		}
530		if *account != "" {
531			// 未出现过的账户余额为 0，且不向状态文件新增账户记录。
532			balance := snapshot.Balances[*account]
533			if cf.asJSON {
534				emitJSON(map[string]any{"treasury": snapshot.Treasury, "account": *account, "balance": balance})
535			} else {
536				fmt.Printf("treasury %d\n%s %d\n", snapshot.Treasury, *account, balance)
537			}
538			return
539		}
540		if cf.asJSON {
541			emitJSON(map[string]any{"treasury": snapshot.Treasury, "balances": snapshot.Balances})
542			return
543		}
544		fmt.Printf("treasury %d\n", snapshot.Treasury)
545		accounts := make([]string, 0, len(snapshot.Balances))
546		for acct := range snapshot.Balances {
547			accounts = append(accounts, acct)
548		}
549		sort.Strings(accounts)
550		for _, acct := range accounts {
551			fmt.Printf("%s %d\n", acct, snapshot.Balances[acct])
552		}
553	}
554	
555	func runProposal(args []string) {
556		cf := newCmdFlags("proposal")
557		id := cf.fs.String("id", "", "proposal id")
558		cf.parse(args)
559		if *id == "" {
560			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
561			os.Exit(2)
562		}
563		store, err := govflow.Open(cf.state)
564		if err != nil {
565			fail(err)
566		}
567		defer store.Close()
568		record, ok, err := store.Proposal(*id)
569		if err != nil {
570			fail(err)
571		}
572		if ok {
573			// 保持既有 JSON 形状：直接输出登记提案记录。
574			if cf.asJSON {
575				emitJSON(record)
576				return
577			}
578			printProposalText(record)
579			return
580		}
581		voteView, vok, verr := store.VoteProposal(*id)
582		if verr != nil {
583			fail(verr)
584		}
585		if !vok {
586			fail(fmt.Errorf("%w: %s", govflow.ErrProposalNotFound, *id))
587		}
588		if cf.asJSON {
589			emitJSON(voteView)
590			return
591		}
592		printVoteProposalText(voteView)
593	}
594	
595	func runProposals(args []string) {
596		cf := newCmdFlags("proposals")
597		cf.parse(args)
598		store, err := govflow.Open(cf.state)
599		if err != nil {
600			fail(err)
601		}
602		defer store.Close()
603		// 一次快照读取保证登记提案与投票提案来自同一份已提交状态，
604		// 不会把并发执行前后的提案状态拼在一起。
605		snapshot, err := store.ProposalsSnapshot()
606		if err != nil {
607			fail(err)
608		}
609		registered := snapshot.Registered
610		voting := snapshot.Voting
611		if cf.asJSON {
612			// 保持既有 JSON 形状：一个数组；登记记录字段不变，投票提案带额外字段。
613			merged := make([]any, 0, len(registered)+len(voting))
614			for _, r := range registered {
615				merged = append(merged, r)
616			}
617			for _, v := range voting {
618				merged = append(merged, v)
619			}
620			emitJSON(merged)
621			return
622		}
623		for _, record := range registered {
624			printProposalText(record)
625		}
626		for _, view := range voting {
627			printVoteProposalText(view)
628		}
629	}
630	
631	func runReceipt(args []string) {
632		cf := newCmdFlags("receipt")
633		id := cf.fs.String("id", "", "proposal id")
634		cf.parse(args)
635		if *id == "" {
636			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
637			os.Exit(2)
638		}
639		store, err := govflow.Open(cf.state)
640		if err != nil {
641			fail(err)
642		}
643		defer store.Close()
644		receipt, ok, err := store.Receipt(*id)
645		if err != nil {
646			fail(err)
647		}
648		if !ok {
649			fail(fmt.Errorf("no execution receipt for proposal %s", *id))
650		}
651		if cf.asJSON {
652			emitJSON(receipt)
653			return
654		}
655		printReceiptText(receipt, true)
656	}
657	
658	func runReceipts(args []string) {
659		cf := newCmdFlags("receipts")
660		cf.parse(args)
661		store, err := govflow.Open(cf.state)
662		if err != nil {
663			fail(err)
664		}
665		defer store.Close()
666		receipts, err := store.Receipts()
667		if err != nil {
668			fail(err)
669		}
670		if cf.asJSON {
671			emitJSON(receipts)
672			return
673		}
674		for _, receipt := range receipts {
675			printReceiptText(receipt, true)
676		}
677	}
678	
679	func printProposalText(p govflow.ProposalRecord) {
680		fmt.Printf("proposal %s state=%s timelock_end=%d actions=%d\n", p.ID, p.State, p.TimelockEnd, len(p.Actions))
681		for i, action := range p.Actions {
682			fmt.Printf("  action %d: %s\n", i, action)
683		}
684	}
685	
686	func printVoteProposalText(v *govflow.VoteProposalView) {
687		fmt.Printf("proposal %s source=vote state=%s quorum=%d voting=[%d,%d) timelock_end=%d actions=%d total_weight=%d\n",
688			v.ID, v.State, v.Quorum, v.StartAt, v.Deadline, v.TimelockEnd, len(v.Actions), v.TotalWeight)
689		for _, m := range v.Members {
690			chain := strings.Join(m.Path, "->")
691			if len(m.Path) == 1 {
692				fmt.Printf("  member %s weight=%d representative=self\n", m.ID, m.Weight)
693			} else {
694				fmt.Printf("  member %s weight=%d path=%s\n", m.ID, m.Weight, chain)
695			}
696		}
697		for i, action := range v.Actions {
698			fmt.Printf("  action %d: %s\n", i, action)
699		}
700		for _, b := range v.Ballots {
701			fmt.Printf("  ballot representative=%s choice=%s weight=%d voted_at=%d\n",
702				b.Representative, choiceWord(b.Support), b.Weight, b.VotedAt)
703		}
704		if v.Tally != nil {
705			verdict := "rejected"
706			if v.Tally.Passed {
707				verdict = "passed"
708			}
709			fmt.Printf("  tally for=%d against=%d turnout=%d => %s tallied_at=%d\n",
710				v.Tally.ForWeight, v.Tally.AgainstWeight, v.Tally.Turnout, verdict, v.Tally.TalliedAt)
711		}
712	}
713	
714	func printReceiptText(r *govflow.Receipt, header bool) {
715		if header {
716			fmt.Printf("receipt proposal=%s order=%d executed_at=%d actions=%d\n", r.ProposalID, r.Order, r.ExecutedAt, len(r.Actions))
717		} else {
718			fmt.Printf("executed proposal %s at %d (%d action(s)); receipt order %d\n", r.ProposalID, r.ExecutedAt, len(r.Actions), r.Order)
719		}
720		for _, ar := range r.Actions {
721			fmt.Printf("  action %d: %s\n", ar.Index, ar.Action)
722			fmt.Printf("    treasury:  %d -> %d\n", ar.Treasury.Before, ar.Treasury.After)
723			fmt.Printf("    %s: %d -> %d\n", ar.Recipient.Account, ar.Recipient.Before, ar.Recipient.After)
724		}
725	}
726	
727	func runDemo() {
728		proposal := govflow.Proposal{ID: "gip-7", Title: "fund the audit workstream", State: "voting", Quorum: 1000,
729			TimelockEnd: 5000, Actions: []string{"transfer:audits:25000"}}
730		if err := govflow.Vote(&proposal, 700, true); err != nil {
731			fmt.Println("vote refused:", err)
732		}
733		if err := govflow.Vote(&proposal, 200, false); err != nil {
734			fmt.Println("vote refused:", err)
735		}
736		next := govflow.Tally(&proposal)
737		fmt.Printf("proposal=%s for=%d against=%d quorum=%d next=%s\n", proposal.ID, proposal.ForVotes, proposal.AgainstVotes, proposal.Quorum, next)
738		proposal.State = next
739		proposal.TimelockEnd = 400
